  (1300, 'pr_narrative', 'pr_narrative', 'github', 'actor-mei', 'project-auth', 'NoxFeed-Demo', 'identity-service', 73, 'I added seamless session rotation so active users keep working while credentials renew safely in the background.', 2700, '{"action":"opened","pr_number":73,"pr":{"number":73,"title":"Rotate short-lived sessions without interrupting users","html_url":"https://github.com/cloudflare/workers-sdk/pull/10000","author":"mei-demo","body":"Renews expiring sessions before they interrupt an active workspace.","head_ref":"feature/session-rotation","base_ref":"main","additions":184,"deletions":41,"changed_files":7,"draft":false}}'),
